#!/usr/bin/env ruby
# frozen_string_literal: true

# COLD_PROFILE (tools/bc2cpp/cold_compact.rb): turns a profiled host sweep into the cold method list.
#
# Usage: ruby scripts/bc2cpp/cold_profile.rb BUILD_DIR COUNTS_DIR OUT [MAX_CALLS]
#   BUILD_DIR   a closed build generated with BC2CPP_COLD_PROFILE=1; every method its generated files count is a
#               candidate, so one the sweep never calls is cold too.
#   COUNTS_DIR  the cold-*.tsv files the profiled host wrote (BC2CPP_COLD_PROFILE_DIR).
#   OUT         the list to write (the world's sig/bc2cpp/cold_methods.txt).
#   MAX_CALLS   a method called at most this many times over the whole sweep is cold (default 0).
# Prints the call-count distribution, which is what the threshold is chosen from.

build, counts_dir, out, max = ARGV
abort 'usage: cold_profile.rb BUILD_DIR COUNTS_DIR OUT [MAX_CALLS]' unless build && counts_dir && out
max = Integer(max || '0')

keys = Dir[File.join(build, 'closed/mrbgems/**/*_gen*.cpp')].sort.flat_map do |path|
  File.read(path).scan(/BC2CPP_COLD_PROFILE_HIT\("([^"]+)"\)/).flatten
end.uniq
abort "cold_profile: #{build} has no BC2CPP_COLD_PROFILE_HIT; build it with BC2CPP_COLD_PROFILE=1" if keys.empty?

calls = Hash.new(0)
files = Dir[File.join(counts_dir, 'cold-*.tsv')]
abort "cold_profile: no cold-*.tsv in #{counts_dir}" if files.empty?
files.each do |path|
  File.foreach(path) do |line|
    key, n = line.chomp.split("\t")
    calls[key] += Integer(n)
  end
end
unknown = calls.keys - keys
warn "cold_profile: #{unknown.size} counted method(s) not in the generated files" unless unknown.empty?

totals = keys.map { |k| calls[k] }
puts "methods #{keys.size}, count files #{files.size}"
[0, 1, 10, 100, 1_000, 10_000, 100_000].each do |bound|
  puts format('  called <= %-7d %5d', bound, totals.count { |n| n <= bound })
end
cold = keys.select { |k| calls[k] <= max }.sort
File.write(out, <<~HEAD + cold.join("\n") + "\n")
  # COLD_COMPACT (bc2cpp tools/bc2cpp/cold_compact.rb): compiled methods the host sweep calls at most #{max} times.
  # Generated by scripts/bc2cpp/cold_profile.bash; a method not listed keeps the inline code.
HEAD
puts "cold #{cold.size} (<= #{max} calls) -> #{out}"
